function Confirm([bool]$Condition,[string]$Name){
    if($Condition){$script:passes++;return}
    $script:failures.Add($Name)
}

function Get-TestIdentity([string]$Path){
    $bytes=[IO.File]::ReadAllBytes($Path);$sha=[Security.Cryptography.SHA256]::Create()
    try{return $bytes.Length.ToString()+'|'+([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')}
    finally{$sha.Dispose()}
}

function Get-TestBytesIdentity([byte[]]$Bytes){
    $sha=[Security.Cryptography.SHA256]::Create()
    try{return $Bytes.Length.ToString()+'|'+([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','')}
    finally{$sha.Dispose()}
}

function Get-TestTreeIdentity([string]$Root){
    $resolved=[IO.Path]::TrimEndingDirectorySeparator([IO.Path]::GetFullPath($Root))
    [string[]]$records=@(Get-ChildItem -LiteralPath $resolved -Recurse -File -Force|ForEach-Object{$relative=$_.FullName.Substring($resolved.Length+1).Replace('\','/');$relative+'|'+(Get-TestIdentity $_.FullName)})
    [Array]::Sort($records,[StringComparer]::Ordinal)
    return Get-TestBytesIdentity ([Text.UTF8Encoding]::new($false).GetBytes([string]::Join("`n",$records)))
}

function Write-TestUtf8([string]$Path,[string]$Text){
    $parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null}
    [IO.File]::WriteAllText($Path,$Text.Replace("`r`n","`n").Replace("`r","`n"),[Text.UTF8Encoding]::new($false))
}

function Seal-TestFrameworkFixture([string]$VersionRoot){
    $versionPath=Join-Path $VersionRoot 'VERSION.json';$version=Get-Content -Raw -Encoding utf8 -LiteralPath $versionPath|ConvertFrom-Json;$version.lifecycle='STABLE';$version.consumable=$true;$version.projectPinEligible=$true;Write-TestUtf8 $versionPath (($version|ConvertTo-Json -Depth 20)+"`n")
    $loadPath=Join-Path $VersionRoot 'LOAD_MANIFEST.json';$load=Get-Content -Raw -Encoding utf8 -LiteralPath $loadPath|ConvertFrom-Json;$load.lifecycle='STABLE';Write-TestUtf8 $loadPath (($load|ConvertTo-Json -Depth 30)+"`n")
    [string[]]$files=@(Get-ChildItem -LiteralPath $VersionRoot -Recurse -File -Force|ForEach-Object{$_.FullName.Substring($VersionRoot.Length+1).Replace('\','/')}|Where-Object{$_-cne'RELEASE_MANIFEST.json'});[Array]::Sort($files,[StringComparer]::Ordinal)
    [int64]$total=0;$rows=@();foreach($relative in $files){$identity=(Get-TestIdentity (Join-Path $VersionRoot $relative)).Split('|');$total+=[int64]$identity[0];$rows+=($relative+'|'+$identity[0]+'|'+$identity[1])}
    $canonical=(Get-TestBytesIdentity ([Text.UTF8Encoding]::new($false).GetBytes([string]::Join("`n",$rows)))).Split('|')[1]
    $manifestPath=Join-Path $VersionRoot 'RELEASE_MANIFEST.json';$reviewedManifestIdentity=Get-TestIdentity $manifestPath;$manifest=Get-Content -Raw -Encoding utf8 -LiteralPath $manifestPath|ConvertFrom-Json;$manifest.lifecycle='STABLE';$manifest.fileCount=$files.Count;$manifest.totalBytes=$total;$manifest.canonical=$canonical;$manifest.sourceReview='APPROVED';$manifest.sourceCandidate='TEST_FIXTURE_CANDIDATE';$manifest.completeSuite=[pscustomobject][ordered]@{status='PASS';passed=1;total=1;payloadCanonical=$canonical;evidenceIdentity=('1|'+('A'*64))};$manifest.sourceReviewEvidence=[pscustomobject][ordered]@{status='APPROVED';reviewer='fixture-reviewer';packageIdentity=('1|'+('B'*64));reviewedPayloadCanonical=$canonical;reviewedManifestIdentity=$reviewedManifestIdentity};$manifest.releaseIntegration='ROOT_MAINTENANCE_TEST';Write-TestUtf8 $manifestPath (($manifest|ConvertTo-Json -Depth 20)+"`n")
}

function Approve-TestLocalCandidate([string]$VersionRoot){
    [string[]]$files=@(Get-ChildItem -LiteralPath $VersionRoot -Recurse -File -Force|ForEach-Object{$_.FullName.Substring($VersionRoot.Length+1).Replace('\','/')}|Where-Object{$_-cne'RELEASE_MANIFEST.json'});[Array]::Sort($files,[StringComparer]::Ordinal)
    [int64]$total=0;$rows=@();foreach($relative in $files){$identity=(Get-TestIdentity (Join-Path $VersionRoot $relative)).Split('|');$total+=[int64]$identity[0];$rows+=($relative+'|'+$identity[0]+'|'+$identity[1])}
    $canonical=(Get-TestBytesIdentity ([Text.UTF8Encoding]::new($false).GetBytes([string]::Join("`n",$rows)))).Split('|')[1]
    $manifestPath=Join-Path $VersionRoot 'RELEASE_MANIFEST.json';$reviewedManifestIdentity=Get-TestIdentity $manifestPath;$manifest=Get-Content -Raw -Encoding utf8 -LiteralPath $manifestPath|ConvertFrom-Json
    $manifest.schemaVersion=2;$manifest.lifecycle='CANDIDATE';$manifest.fileCount=$files.Count;$manifest.totalBytes=$total;$manifest.canonical=$canonical;$manifest.sourceReview='APPROVED';$manifest.sourceCandidate='TEST_FIXTURE_REVIEWED_LOCAL_CANDIDATE';$manifest.completeSuite=[pscustomobject][ordered]@{status='PASS';passed=17;total=17;payloadCanonical=$canonical;evidenceIdentity=('1|'+('C'*64))};$manifest.sourceReviewEvidence=[pscustomobject][ordered]@{status='APPROVED';reviewer='fixture-reviewer';packageIdentity=('1|'+('D'*64));reviewedPayloadCanonical=$canonical;reviewedManifestIdentity=$reviewedManifestIdentity};$manifest.releaseIntegration='PENDING'
    Write-TestUtf8 $manifestPath (($manifest|ConvertTo-Json -Depth 20)+"`n")
}

function New-TestGitRepo([string]$Path){New-Item -ItemType Directory -Path $Path -Force|Out-Null;& git -C $Path init -q;if($LASTEXITCODE-ne0){throw 'TEST_GIT_INIT_FAILED'};& git -C $Path config core.autocrlf false}

function Add-TestRootToolFixture([string]$Workspace) {
    foreach($relative in @(
        'scripts/upgrade-project.ps1',
        'scripts/register-project.ps1',
        'scripts/MaintenanceOverlay.psm1',
        'scripts/ProjectAdoptionState.psm1',
        'scripts/ProjectAdoptionProjection.psm1',
        'scripts/ProjectAdoptionTransaction.psm1',
        'skills/ai-workspace-router/SKILL.md'
    )) {
        $source=Join-Path $RepositoryRoot $relative
        $destination=Join-Path $Workspace $relative
        $parent=Split-Path -Parent $destination
        if(-not(Test-Path -LiteralPath $parent -PathType Container)){New-Item -ItemType Directory -Path $parent -Force|Out-Null}
        Copy-Item -LiteralPath $source -Destination $destination -Force
    }
}

function Render-TestMaintenanceControl([string]$Starter,[string]$ControlRoot,[string]$ProjectId,[string]$Version){
    $controlPlane=Join-Path $ControlRoot '.ai-workspace';New-Item -ItemType Directory -Path $controlPlane -Force|Out-Null
    foreach($file in @(Get-ChildItem -LiteralPath $Starter -Recurse -File -Force)){$relative=$file.FullName.Substring($Starter.Length+1);$destination=if($relative-ceq'AGENTS.md'){Join-Path $ControlRoot 'AGENTS.md'}else{Join-Path $controlPlane $relative};$text=Get-Content -LiteralPath $file.FullName -Raw -Encoding utf8;$text=$text.Replace('{{PROJECT_ID}}',$ProjectId).Replace('{{DISPLAY_NAME}}','Maintenance Upgrade Fixture').Replace('{{FRAMEWORK_VERSION}}',$Version).Replace('{{CONTROLLER_ID}}','controller-fixture');Write-TestUtf8 $destination $text}
    return $controlPlane
}

$repairTempPaths=New-Object 'System.Collections.Generic.List[string]'
function New-TestCorrectionsRepairSource([string]$RepositoryRoot,[string]$Text){
    $runtimeRoot=Join-Path $RepositoryRoot '.ai-workspace/runtime/SAME-PIN-MIGRATION-001/controller-fixture'
    New-Item -ItemType Directory -Path $runtimeRoot -Force|Out-Null
    $path=Join-Path $runtimeRoot ('project-corrections-repair-'+[guid]::NewGuid().ToString('N')+'.json')
    Write-TestUtf8 $path $Text
    $script:repairTempPaths.Add($path)
    return [pscustomobject]@{Path=$path;Identity=(Get-TestIdentity $path)}
}

